-- =========================================================================
-- BANCO DE DADOS: RH & RECURSOS HUMANOS (semana08-01-base-rh-500.sql)
-- Tabela única de RH contendo 500 registros para aulas de Funções Nativas
-- Compatível com MySQL, MariaDB e SQLite
-- =========================================================================

CREATE DATABASE IF NOT EXISTS db_rh;
USE db_rh;

DROP TABLE IF EXISTS tb_funcionarios_rh;

CREATE TABLE tb_funcionarios_rh (
    id_funcionario INTEGER PRIMARY KEY AUTO_INCREMENT ,
    nome_funcionario VARCHAR(50) NOT NULL,
    sobrenome_funcionario VARCHAR(50) NOT NULL,
    cpf VARCHAR(14) NOT NULL,
    cargo VARCHAR(50) NOT NULL,
    departamento VARCHAR(50) NOT NULL,
    salario_base DECIMAL(10,2) NOT NULL,
    data_contratacao DATE NOT NULL,
    email_pessoal VARCHAR(100),
    telefone VARCHAR(20),
    cidade VARCHAR(50) NOT NULL,
    ativo BOOLEAN NOT NULL DEFAULT 1
);

